PRAGMA foreign_keys = ON;
BEGIN;




-- Lote de 48 etiquetas ya impreso (QR con solo el ID, formato antiguo)
WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i+1 FROM n WHERE i < 48)



COMMIT;
